      SpatialQuery.EncodedRectangle bbox,
      int pMaxX,
      int pMaxY,
      double x,
      Component2D queryComponent2D)
      throws IOException {
    Relation r = Relation.CELL_OUTSIDE_QUERY;
    if (type == TYPE.POINT) {
      r = relatePoint(bbox, pMaxY, x, queryComponent2D);
    } else if (type == TYPE.LINE) {
